from pathlib import Path
import json

TEMPLATE=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>期刊图件 · 直接 PDF 候选工作台</title>
<style>
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#242a32;background:#f5f6f7;font-size:14px}*{box-sizing:border-box}body{margin:0}header{height:64px;background:#202933;color:white;padding:12px 22px;display:flex;align-items:center;justify-content:space-between}header b{font-size:18px}header small{display:block;color:#b9c6d0;margin-top:3px}.pill{border:1px solid #8197a7;border-radius:20px;padding:5px 12px;font-size:12px}.wrap{display:grid;grid-template-columns:225px 1fr;min-height:calc(100vh - 64px)}aside{background:white;border-right:1px solid #ddd;padding:16px 12px}aside h3{font-size:13px;color:#78818a;margin:16px 8px 8px}.card{padding:10px;margin:5px 0;border:1px solid #dce2e5;border-radius:6px;cursor:pointer}.card:hover,.card.active{border-color:#3c6478;background:#edf3f6}.card small{display:block;color:#65717c;margin-top:4px}main{padding:16px 22px;min-width:0}.title{display:flex;justify-content:space-between;align-items:center}.title h2{font-size:20px;margin:0 0 5px}.sub{font-size:12px;color:#68727b}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;background:white;border:1px solid #e0e3e5;border-radius:6px;padding:10px;margin:15px 0}.toolbar label{font-size:12px}button,select,input{padding:6px 9px;font:inherit;border:1px solid #c5cdd3;border-radius:4px;background:white}button{cursor:pointer}button.primary{background:#31576e;color:white;border-color:#31576e}button:disabled{opacity:.45;cursor:wait}.views{display:grid;grid-template-columns:1fr 1fr;gap:14px}.panel{background:white;border:1px solid #e0e3e5;border-radius:6px;overflow:hidden}.panel h3{font-size:13px;font-weight:500;margin:0;padding:10px 14px;background:#f9fafb;border-bottom:1px solid #eee}.imagebox{min-height:340px;max-height:680px;overflow:auto;padding:22px;display:flex;align-items:flex-start;justify-content:center}.imagebox img{display:block;max-width:100%;height:auto;max-height:620px;object-fit:contain}.notes{display:grid;grid-template-columns:1.2fr 1fr;gap:14px;margin-top:14px}.warn{padding:12px 14px;background:#fff9e9;border:1px solid #ead8a5;border-radius:6px;font-size:13px;line-height:1.65}.warn p{margin:5px 0}.review{background:white;border:1px solid #ddd;border-radius:6px;padding:12px}textarea{width:100%;min-height:95px;padding:9px;font:inherit;resize:vertical;border:1px solid #d2d9de;border-radius:4px}.review button{margin-top:6px}a{color:#31576e}pre{font-size:11px;white-space:pre-wrap;word-break:break-word;max-height:350px;overflow:auto;background:white;padding:12px}.foot{color:#78818a;font-size:12px;margin:12px 0}#message{margin-left:8px;color:#8a611f}.stats{display:flex;gap:15px;flex-wrap:wrap;margin:8px 0;color:#54616b;font-size:12px}@media(max-width:900px){.wrap{grid-template-columns:165px 1fr}.views,.notes{grid-template-columns:1fr}main{padding:12px}.imagebox{min-height:200px}}</style>
<header><div><b>期刊图件 · 直接 PDF</b><small>候选模块　/　原图形保护 · 文字排版 · 多图种输出</small></div><span class="pill">候选测试 · 不自动进入排版定稿</span></header>
<div class="wrap"><aside id="nav"></aside><main><div class="title"><div><h2 id="title"></h2><div class="sub" id="subtitle"></div></div><a id="pdf" target="_blank">打开单图 PDF ↗</a></div>
<div class="stats" id="stats"></div><div class="toolbar"><label>栏宽 <select id="column"><option value="single">单栏</option><option value="double">双栏</option><option value="auto">自动试排</option></select></label><label>字号 <select id="font"><option value="auto">8 pt优先，按整图适配</option><option>8</option><option>7</option><option>6</option></select></label><label id="plotlabel">绘图区宽 <input id="plotwidth" type="number" min="15" max="130" step="0.5" style="width:70px"> mm</label><label id="legendlabel">图例 <select id="legend"><option value="upper-right">图内右上</option><option value="lower-right">图内右下</option><option value="source-region">原图安全区域</option><option value="outside-top">图外上方</option></select></label><button id="apply" class="primary">重排并生成候选 PDF</button><span id="message"></span></div>
<div class="views"><section class="panel"><h3>配套参考 / 原图（未改动）</h3><div class="imagebox"><img id="before" alt="参考图"><span id="noref" hidden>未提供配套参考预览</span></div></section><section class="panel"><h3>实际生成 PDF 的渲染预览</h3><div class="imagebox"><img id="after" alt="实际PDF预览"></div></section></div>
<div class="notes"><div class="warn" id="warnings"></div><div class="review"><b>本地审核备注</b><p class="sub">只保存候选备注，不改正式验收状态。</p><textarea id="note" placeholder="记录需要调整的文字、间距、图例或对应关系"></textarea><button id="save">保存备注</button><span id="saved" class="sub"></span></div></div>
<details style="margin-top:14px"><summary>查看制作与检查记录</summary><pre id="details"></pre></details><div class="foot">字体目录扫描次数：<b id="scan"></b>。缓存命中不重复发现字体；配置文件或字体变化时才重新校验。此版本未执行 InDesign 置入终检。</div></main></div>
<script>const DATA=__DATA__;const API_TOKEN=__TOKEN__;const PREFIX=__PREFIX__;let current=null;const notes={};const $=id=>document.getElementById(id);const url=p=>PREFIX+encodeURI(p);function group(){const nav=$('nav');nav.replaceChildren();if(DATA.failures?.length){let w=document.createElement('div');w.className='warn';w.id='blocked-summary';w.textContent='受阻 '+DATA.failures.length+' 张：'+DATA.failures.map(x=>x.id+'（'+(x.error?.message||'需检查')+'）').join('；')+'。先修正制作说明，再用新目录重跑；未计为完成。';nav.append(w)}const authors=[...new Set(DATA.results.map(x=>x.author))];for(const a of authors){let h=document.createElement('h3');h.textContent=a;nav.append(h);for(const r of DATA.results.filter(x=>x.author===a)){let d=document.createElement('div');d.className='card'+(current?.id===r.id?' active':'');let b=document.createElement('b');b.textContent=r.id;let q=document.createElement('small');q.textContent=r.kind+' · '+r.pdf_audit.width_mm.toFixed(1)+' mm';d.append(b,q);d.onclick=()=>show(r);nav.append(d)}}}function show(r){current=r;group();$('title').textContent=r.id;$('subtitle').textContent='直接 PDF / '+r.kind+' / 矢量或混合内容；.ai 不是必交项';$('pdf').href=url(r.output_pdf);$('after').src=url(r.preview);$('before').hidden=!r.reference_preview;$('noref').hidden=!!r.reference_preview;if(r.reference_preview)$('before').src=url(r.reference_preview);$('stats').textContent='成图 '+r.pdf_audit.width_mm.toFixed(2)+' × '+r.pdf_audit.height_mm.toFixed(2)+' mm　|　整图 '+r.layout.layout_evidence.fit_attempts.at(-1).font_size_pt+' pt　|　程序处理 '+r.timings_ms.total.toFixed(0)+' ms　|　文字/字体嵌入/灰度机械检查通过';$('warnings').replaceChildren();for(const w of r.warnings){let p=document.createElement('p');p.textContent='⚑ '+w.message;$('warnings').append(p)}let p=document.createElement('p');p.textContent='内容、拓扑、实际尺寸可读性及真实复合字体仍需最终审核；程序通过不是发表许可。';$('warnings').append(p);$('details').textContent=JSON.stringify({font:r.font,layout:r.layout.layout_evidence,pdf_audit:r.pdf_audit,assets:r.assets},null,2);$('plotlabel').hidden=r.kind!=='chart';$('legendlabel').hidden=r.kind!=='chart';$('plotwidth').value=r.layout.layout_evidence.plot_width_pt?(r.layout.layout_evidence.plot_width_pt*25.4/72).toFixed(2):'';$('legend').value=r.layout.layout_evidence.legend_placement||'upper-right';$('column').value=r.editable_policy?.column||'single';$('font').value=r.editable_policy?.font_sizes?.length===1?String(r.editable_policy.font_sizes[0]):'auto';$('note').value=notes[r.id]||'';$('scan').textContent=DATA.font_cache.stats.directory_scans;$('message').textContent=API_TOKEN?'':'静态查看版；运行本地工作台可重排。';$('apply').disabled=!API_TOKEN;$('save').disabled=!API_TOKEN}
async function post(path,body){const res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-JFW-Token':API_TOKEN},body:JSON.stringify(body)});const j=await res.json();if(!res.ok)throw Error(j.error?.message||j.message||'请求失败');return j}
$('apply').onclick=async()=>{if(!current)return;$('apply').disabled=true;$('message').textContent='正在重排和检查…';try{const changes={column:$('column').value,font_size:$('font').value};if(current.kind==='chart'){changes.plot_width_mm=Number($('plotwidth').value);changes.legend_placement=$('legend').value}const j=await post('/api/render',{id:current.id,changes});const old=DATA.results.findIndex(x=>x.id===j.id);DATA.results[old]=j;show(j);$('message').textContent='已生成新候选版本，未覆盖原稿。'}catch(e){$('message').textContent=e.message}finally{$('apply').disabled=false}};
$('save').onclick=async()=>{try{notes[current.id]=$('note').value;await post('/api/note',{id:current.id,text:$('note').value});$('saved').textContent='已保存'}catch(e){$('saved').textContent=e.message}};if(DATA.results.length)show(DATA.results[0]);else{group();$('title').textContent='本批尚无可查看的成功候选';$('apply').disabled=true;$('save').disabled=true;$('pdf').hidden=true;$('message').textContent='检查左侧受阻原因及失败报告。'}if(API_TOKEN)fetch('/api/notes').then(r=>r.json()).then(j=>{Object.assign(notes,j);if(current)$('note').value=notes[current.id]||''});
</script></html>'''


def gallery_html(report,token=None,prefix=''):
    # Prevent data containing </script> from escaping the inert JSON literal.
    data=json.dumps(report,ensure_ascii=False).replace('</','<\\/')
    return TEMPLATE.replace('__DATA__',data).replace('__TOKEN__',json.dumps(token)).replace('__PREFIX__',json.dumps(prefix))


def make_gallery(report,output:Path):
    (output/'查看样张.html').write_text(gallery_html(report),encoding='utf-8')
